from copy import deepcopy


class ReadingVault:
    def __init__(self):
        self._readings = {}

    @staticmethod
    def _name(name):
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        name = name.strip()
        if not name:
            raise ValueError("name must be non-empty")
        return name

    def put(self, name, payload):
        name = self._name(name)
        if not isinstance(payload, dict):
            raise TypeError("payload must be a dictionary")
        self._readings[name] = deepcopy(payload)
        return name

    def get(self, name):
        name = self._name(name)
        if name not in self._readings:
            raise KeyError(name)
        return deepcopy(self._readings[name])

    def snapshot(self):
        return {name: self._readings[name] for name in sorted(self._readings)}

    def names(self):
        return sorted(self._readings)
```

